@font-face {
    font-family: 'NMSFuturaProBook';
    src: url('../resources/fonts/NMSFuturaProBook_Kerned.ttf') format('truetype');
    font-weight: normal;
    font-style: normal;
}

*
{
    box-sizing: border-box;
    margin: 0;
    font-family: 'NMSFuturaProBook';
}

:root
{
    /* ==========================================================================
       1. FLUID RESPONSIVE MEASUREMENT TOKENS (Continuous clamp() Math)
       ========================================================================== */
    --app-height: 100dvh;
    --app-width: 100dvw;
    --safe-top: max(0.5rem, env(safe-area-inset-top));
    --safe-bottom: max(0.75rem, env(safe-area-inset-bottom));
    --safe-left: env(safe-area-inset-left);
    --safe-right: env(safe-area-inset-right);

    /* Fluid Typography Scale (1.25 Major Third Harmonic Curve) */
    --font-3xs: clamp(0.5625rem, 0.52rem + 0.10vw, 0.625rem); /* 9px - 10px */
    --font-2xs: clamp(0.625rem, 0.58rem + 0.15vw, 0.6875rem); /* 10px - 11px */
    --font-xs:  clamp(0.6875rem, 0.64rem + 0.20vw, 0.75rem);   /* 11px - 12px */
    --font-sm:  clamp(0.75rem, 0.70rem + 0.25vw, 0.875rem);   /* 12px - 14px */
    --font-base:clamp(0.875rem, 0.82rem + 0.30vw, 1.00rem);   /* 14px - 16px */
    --font-md:  clamp(1.00rem, 0.92rem + 0.40vw, 1.25rem);    /* 16px - 20px */
    --font-lg:  clamp(1.25rem, 1.10rem + 0.75vw, 1.75rem);    /* 20px - 28px */
    --font-xl:  clamp(1.50rem, 1.25rem + 1.25vw, 2.25rem);    /* 24px - 36px */
    --font-display: clamp(1.75rem, 1.40rem + 1.75vw, 2.75rem);/* 28px - 44px */

    /* Fluid Spacing Scale (8pt / 4pt Rhythm) */
    --space-3xs: clamp(0.125rem, 0.10rem + 0.1vw, 0.25rem);   /* 2px - 4px */
    --space-2xs: clamp(0.25rem, 0.20rem + 0.2vw, 0.375rem);   /* 4px - 6px */
    --space-xs:  clamp(0.375rem, 0.30rem + 0.3vw, 0.50rem);   /* 6px - 8px */
    --space-sm:  clamp(0.50rem, 0.40rem + 0.4vw, 0.75rem);    /* 8px - 12px */
    --space-md:  clamp(0.75rem, 0.60rem + 0.6vw, 1.25rem);    /* 12px - 20px */
    --space-lg:  clamp(1.00rem, 0.80rem + 1.0vw, 1.75rem);    /* 16px - 28px */
    --space-xl:  clamp(1.50rem, 1.20rem + 1.5vw, 2.50rem);    /* 24px - 40px */
    --space-2xl: clamp(2.00rem, 1.60rem + 2.0vw, 3.50rem);    /* 32px - 56px */

    /* Ergonomic Touch Targets (Fitts's Law & Touch Accessibility) */
    --touch-min: max(44px, 2.75rem);
    --slider-scrub-zone: max(36px, 2.25rem);

    /* Adaptive Component Dimensions */
    --topbar-height: clamp(3.0rem, 5.5dvh, 4.0rem);
    --bottom-deck-height: clamp(4.5rem, 9.0dvh, 6.0rem);
    --turntable-size: clamp(13.5rem, min(75cqi, 40dvh), 23rem);

    /* Border Radius Scale */
    --radius-xs: 3px;
    --radius-sm: 6px;
    --radius-md: 10px;
    --radius-lg: 16px;
    --radius-full: 9999px;

    /* Transitions */
    --transition-fast: 0.15s cubic-bezier(0.4, 0, 0.2, 1);
    --transition-base: 0.25s cubic-bezier(0.16, 1, 0.3, 1);
    --transition-smooth: 0.4s cubic-bezier(0.16, 1, 0.3, 1);

    /* ==========================================================================
       2. DEFAULT THEME: TACTILE CYBER WORKSTATION (Dark Teal & Laser Cyan)
       Strict WCAG 2.1 AAA Contrast Hierarchy
       ========================================================================== */
    --bg-canvas: #070a0e;
    --bg-surface-1: rgba(13, 20, 28, 0.94);
    --bg-surface-2: rgba(20, 31, 44, 0.94);
    --bg-surface-3: rgba(28, 43, 62, 0.96);
    --bg-glass: rgba(7, 10, 14, 0.88);

    --border-subtle: rgba(255, 255, 255, 0.10);
    --border-medium: rgba(0, 229, 255, 0.30);
    --border-bold: rgba(0, 229, 255, 0.65);
    --border-focus: #00e5ff;

    --text-primary: #f0f6fc;       /* 17.2:1 contrast against canvas */
    --text-secondary: #a3c7ed;     /* 9.1:1 contrast (WCAG AAA) */
    --text-muted: #6e8fae;         /* 5.2:1 contrast (WCAG AA) */
    --text-disabled: #40576e;
    --text-accent: #00e5ff;
    --text-on-accent: #040e14;     /* 14.8:1 contrast on cyan button/badge */

    --accent-color: #00e5ff;
    --accent-hover: #33ebff;
    --accent-glow: rgba(0, 229, 255, 0.45);
    --accent-surface: rgba(0, 229, 255, 0.14);
    --ambient-aura-1: rgba(0, 229, 255, 0.20);
    --ambient-aura-2: rgba(0, 229, 255, 0.04);

    --status-success: #10b981;
    --status-warning: #f59e0b;
    --status-danger: #ef4444;
}

