html, body
{
    width: 100%;
    height: 100%;
    height: 100dvh;
    margin: 0;
    padding: 0;
    overflow: hidden;
    overscroll-behavior: none;
}

body
{
    position: relative;
    display: flex;
    flex-direction: column;
    background-color: var(--bg-canvas, #070a0e);
    color: var(--text-primary, #f0f6fc);
    font-size: var(--font-base, 1rem);
    min-height: var(--app-height, 100dvh);
    height: var(--app-height, 100dvh);
    user-select: none;
    transition: background-color var(--transition-base, 0.25s ease), color var(--transition-base, 0.25s ease);
}

/* Background Turntable Vinyl Graphic */
.bgDisc
{
    position: absolute;
    display: flex;
    justify-content: center;
    align-items: center;
    height: 90rem;
    width: 90rem;
    background-color: rgba(255, 255, 255, 0.03);
    border-radius: 100%;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%) translateZ(0);
    pointer-events: none;
    z-index: 0;
    contain: strict;
}

.bgDisc .inner
{
    position: absolute;
    height: 55rem;
    width: 55rem;
    background-color: black;
    border-radius: 100%;
}

.bgDisc .middle
{
    position: absolute;
    height: 68rem;
    width: 68rem;
    border-radius: 100%;
    border: 1.8rem dashed rgba(255, 255, 255, 0.07);
    animation: gear 25s linear infinite;
    will-change: transform;
    transform: translateZ(0);
}

.bgDisc .outer
{
    position: absolute;
    height: 78rem;
    width: 78rem;
    border-radius: 100%;
    border: 1.8rem solid rgba(255, 255, 255, 0.05);
}

.bgDisc.fast .middle
{
    animation-duration: 8s;
}

/* Background Calligraphy Watermark */
.bgWatermark
{
    position: absolute;
    left: -2rem;
    bottom: -2rem;
    height: 38rem;
    width: 38rem;
    opacity: 0.06;
    pointer-events: none;
    z-index: 0;
    filter: invert(1);
    transition: opacity 0.3s;
}

/* Dynamic Acoustic Atmosphere (Ambient Room Bleed) */
.ambientAtmosphere
{
    position: fixed;
    inset: 0;
    pointer-events: none;
    z-index: 0;
    overflow: hidden;
    opacity: 0.9;
    contain: strict;
    transform: translateZ(0);
    transition: opacity 1s ease;
}

.ambientAuraGlow
{
    position: absolute;
    top: 25%;
    left: 50%;
    transform: translate3d(-50%, -50%, 0);
    width: clamp(38rem, 65vw, 85rem);
    height: clamp(28rem, 50vh, 58rem);
    background: radial-gradient(
        ellipse at center,
        var(--ambient-aura-1, rgba(230, 0, 0, 0.18)) 0%,
        var(--ambient-aura-1, rgba(230, 0, 0, 0.12)) 24%,
        var(--ambient-aura-2, rgba(230, 0, 0, 0.05)) 50%,
        var(--ambient-aura-2, rgba(230, 0, 0, 0.015)) 70%,
        transparent 86%
    );
    contain: layout paint;
    transition: background 1.4s cubic-bezier(0.16, 1, 0.3, 1), opacity 0.8s ease;
    will-change: transform, opacity;
}

body.is-playing .ambientAuraGlow
{
    animation: ambientAuraBreathe 6.5s ease-in-out infinite alternate;
}

@keyframes ambientAuraBreathe
{
    0% { transform: translate3d(-50%, -50%, 0) scale(0.95); opacity: 0.75; }
    100% { transform: translate3d(-50%, -50%, 0) scale(1.08); opacity: 0.98; }
}

/* Top Navigation Bar */
.topBar
{
    display: flex;
    justify-content: space-between;
    align-items: center;
    height: var(--topbar-height, 3.5rem);
    padding: 0 var(--space-md, 1rem);
    padding-top: var(--safe-top, 0.5rem);
    padding-left: max(var(--space-md, 1rem), var(--safe-left, 0px));
    padding-right: max(var(--space-md, 1rem), var(--safe-right, 0px));
    background-color: var(--bg-surface-1, rgba(6, 6, 8, 0.88));
    backdrop-filter: blur(20px);
    -webkit-backdrop-filter: blur(20px);
    border-bottom: 1px solid var(--border-subtle, rgba(255, 255, 255, 0.08));
    z-index: 20;
    position: relative;
    flex-shrink: 0;
    gap: var(--space-sm, 0.75rem);
}

.brand
{
    display: flex;
    align-items: center;
    gap: var(--space-xs, 0.5rem);
    flex-shrink: 0;
}

.brandLogo
{
    font-size: var(--font-lg, 1.4rem);
    color: var(--text-primary, #ffffff);
    letter-spacing: 0.06em;
    line-height: 1;
    white-space: nowrap;
}

/* Brand Mini Equalizer Spectrum */
.brandLiveMeter
{
    display: inline-flex;
    align-items: flex-end;
    gap: 2.5px;
    height: 14px;
    padding: 0 4px;
    opacity: 0.65;
    transition: opacity var(--transition-base, 0.3s ease);
}

.brandLiveMeter .meterBar
{
    width: 2.5px;
    height: 14px;
    background: var(--accent-color, #00e5ff);
    border-radius: 1px;
    transform-origin: bottom;
    transform: scaleY(0.2) translateZ(0);
    will-change: transform;
    transition: background-color var(--transition-base, 0.3s ease);
}

body.is-playing .brandLiveMeter
{
    opacity: 1;
}

body.is-playing .brandLiveMeter .b1 { animation: brandEq1 0.85s ease-in-out infinite alternate; }
body.is-playing .brandLiveMeter .b2 { animation: brandEq2 0.70s ease-in-out infinite alternate 0.15s; }
body.is-playing .brandLiveMeter .b3 { animation: brandEq3 0.95s ease-in-out infinite alternate 0.25s; }
body.is-playing .brandLiveMeter .b4 { animation: brandEq4 0.78s ease-in-out infinite alternate 0.08s; }

@keyframes brandEq1 { 0% { transform: scaleY(0.22) translateZ(0); } 100% { transform: scaleY(0.93) translateZ(0); } }
@keyframes brandEq2 { 0% { transform: scaleY(0.28) translateZ(0); } 100% { transform: scaleY(0.78) translateZ(0); } }
@keyframes brandEq3 { 0% { transform: scaleY(0.18) translateZ(0); } 100% { transform: scaleY(1.00) translateZ(0); } }
@keyframes brandEq4 { 0% { transform: scaleY(0.35) translateZ(0); } 100% { transform: scaleY(0.72) translateZ(0); } }

