}

/* Main Grid Layout */
.gridContainer
{
    display: grid;
    grid-template-columns: minmax(17rem, 22rem) 1fr minmax(18rem, 25rem);
    flex: 1;
    height: auto;
    min-height: 0;
    gap: clamp(0.5rem, 1vw, 1.2rem);
    padding: clamp(0.4rem, 1vh, 0.9rem) clamp(0.8rem, 1.5vw, 1.4rem);
    z-index: 5;
    overflow: hidden;
}

/* Standard Panel Card Style */
.panel
{
    background-color: white;
    color: #111111;
    border-radius: 0.5rem;
    border: 0.15rem solid black;
    box-shadow: 0 0 1rem rgba(0, 0, 0, 0.85);
    display: flex;
    flex-direction: column;
    overflow: hidden;
    position: relative;
    transition: border-color 0.25s cubic-bezier(0.165, 0.84, 0.44, 1), background-color 0.25s ease, box-shadow 0.25s ease;
    transform: translateZ(0);
    backface-visibility: hidden;
}

.panelHeader
{
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.85rem 1.2rem;
    border-bottom: 0.15rem solid black;
    background-color: #f7f7f7;
}

.panelTitle h2
{
    font-size: 1.35rem;
    letter-spacing: 0.05rem;
    line-height: 1.1;
}

.counter
{
    font-size: 0.85rem;
    color: #ffffff;
    font-weight: bold;
    letter-spacing: 0.05rem;
}

.panelHeader .counter
{
    color: #000000 !important;
    background-color: #e2e2e2 !important;
    border: none !important;
    padding: 0.15rem 0.55rem;
    border-radius: 0.25rem;
    font-size: 0.78rem;
    font-weight: 800;
    letter-spacing: 0.06rem;
}

/* Left Panel: Library & Playlists */
.libraryTabs
{
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    border-bottom: 0.15rem solid black;
    background-color: #eeeeee;
}

.libTab
{
    all: unset;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    text-align: center;
    padding: 0.7rem 0;
    font-size: 1.1rem;
    font-weight: bold;
    letter-spacing: 0.1rem;
    transition: all 0.22s cubic-bezier(0.16, 1, 0.3, 1), transform 0.15s ease;
    color: #222222;
    background-color: #eeeeee;
    user-select: none;
}

.libTab:active
{
    transform: scale(0.97);
}

.libTab,
.libTab *
{
    color: #222222;
}

.libTab:hover,
.libTab:hover *
{
    color: #000000;
}

.libTab.active
{
    background-color: white;
    color: black;
    box-shadow: inset 0 -0.25rem 0 black;
}

.libTab.active,
.libTab.active *
{
    color: black !important;
}

.libraryControls
{
    display: flex;
    flex-direction: column;
    padding: 0.5rem 0.65rem;
    border-bottom: 0.08rem solid #e4e4e4;
    background-color: #fafafa;
    gap: 0.42rem;
    box-sizing: border-box;
    flex-shrink: 0;
}

.sortContainer
{
    display: flex;
    align-items: center;
    gap: 0.45rem;
    width: 100%;
}

.sortContainer label
{
    font-size: 0.72rem;
    font-weight: 800;
    color: #555555;
    white-space: nowrap;
    letter-spacing: 0.04rem;
    text-transform: uppercase;
    flex-shrink: 0;
    user-select: none;
    line-height: 1;
}

.sortSelect
{
    height: 1.85rem;
    line-height: 1.85rem;
    padding: 0 0.5rem;
    font-size: 0.78rem;
    font-weight: 700;
    color: #111111;
    border: 0.08rem solid #222222;
    border-radius: 0.25rem;
    background-color: #ffffff;
    cursor: pointer;
    outline: none;
    box-sizing: border-box;
    transition: all 0.15s ease;
    flex: 1;
    min-width: 0;
    max-width: none;
}

.sortSelect:hover,
.sortSelect:focus
{
    border-color: #000000;
    box-shadow: 0 0 0 1px #000000;
}

.panelActions
{
    display: flex;
    align-items: center;
    gap: 0.3rem;
    width: 100%;
    margin-left: 0;
}

.panelActions .actionBtn
{
    flex: 1;
    min-width: 0;
    height: 1.85rem;
    padding: 0 0.35rem;
    font-size: 0.73rem;
    font-weight: 700;
    letter-spacing: 0.02rem;
    border: none;
    border-radius: 0.25rem;
    background-color: #f2f2f2;
    color: #111111;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    box-sizing: border-box;
    white-space: nowrap;
    text-align: center;
    cursor: pointer;
    line-height: 1;
    transition: all 0.15s ease;
}

.panelActions .actionBtn:hover
{
    background-color: #111111;
    color: #ffffff;
}

.panelActions .actionBtn:active
{
    transform: scale(0.97);
}

.actionBtn
{
    all: unset;
    cursor: pointer;
    font-size: 0.85rem;
    padding: 0.3rem 0.65rem;
    border: 0.1rem solid black;
    border-radius: 0.3rem;
    font-weight: bold;
    letter-spacing: 0.05rem;
    transition: all 0.2s ease;
    text-align: center;
    background-color: white;
    color: #000000;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    box-sizing: border-box;
}

.actionBtn:hover
{
    background-color: black;
    color: white;
}

.actionBtn:disabled,
.actionBtn.disabled,
#settingsHwGainToggleBtn:disabled,
#settingsHwGainToggleBtn.disabled
{
    opacity: 0.42 !important;
    cursor: not-allowed !important;
    pointer-events: none !important;
    filter: grayscale(1) !important;
    border-color: rgba(255, 255, 255, 0.15) !important;
    color: rgba(255, 255, 255, 0.45) !important;
    background: rgba(255, 255, 255, 0.05) !important;
    box-shadow: none !important;
    transform: none !important;
}

:is([data-theme="brutalist-light"], [data-theme="minimalist-light"], [data-theme="minimalist-warm"], :root:not([data-theme])) :is(.actionBtn:disabled, .actionBtn.disabled, #settingsHwGainToggleBtn:disabled, #settingsHwGainToggleBtn.disabled)
{
    border-color: rgba(0, 0, 0, 0.18) !important;
    color: rgba(0, 0, 0, 0.45) !important;
    background: rgba(0, 0, 0, 0.05) !important;
}

.uploadBtn
{
    display: inline-flex;
    margin: 0;
}

@keyframes tabContentFade
{
    0%
    {
        opacity: 0;
        transform: translateY(6px);
    }
    100%
