    border: 0.1rem solid transparent;
    cursor: pointer;
    transition: transform 0.18s cubic-bezier(0.25, 0.1, 0.25, 1), background-color 0.18s cubic-bezier(0.25, 0.1, 0.25, 1), border-color 0.18s cubic-bezier(0.25, 0.1, 0.25, 1), box-shadow 0.18s cubic-bezier(0.25, 0.1, 0.25, 1);
    gap: 0.5rem;
    background-color: #f9f9f9;
}

.trackItem:hover
{
    background-color: white;
    border-color: black;
    transform: translateX(3px);
    box-shadow: 0 0.2rem 0.5rem rgba(0, 0, 0, 0.1);
}

.trackItem.active
{
    background-color: black;
    border-color: black;
    box-shadow: 0 0.25rem 0.8rem rgba(0, 0, 0, 0.35);
}

.trackItem.active *
{
    color: white !important;
}

.trackThumb
{
    width: 2.25rem;
    height: 2.25rem;
    border-radius: 0.25rem;
    object-fit: cover;
    border: 0.08rem solid #ccc;
    background-color: black;
    flex-shrink: 0;
}

.trackIndex
{
    font-size: 0.85rem;
    font-weight: bold;
    width: 1.2rem;
    text-align: center;
    color: #888888;
    flex-shrink: 0;
}

.trackItem.active .trackIndex
{
    display: none;
}

.miniEq
{
    display: none;
    align-items: flex-end;
    gap: 0.15rem;
    height: 1rem;
    width: 1.4rem;
}

.trackItem.active .miniEq
{
    display: flex;
}

.miniEq span
{
    width: 0.22rem;
    height: 100%;
    background-color: white;
    border-radius: 0.1rem;
    transform-origin: bottom;
    transform: scaleY(0.2) translateZ(0);
    will-change: transform;
    animation: miniBounce 0.8s ease-in-out infinite alternate;
}

.miniEq span:nth-child(1) { animation-delay: 0.1s; }
.miniEq span:nth-child(2) { animation-delay: 0.3s; }
.miniEq span:nth-child(3) { animation-delay: 0.2s; }

@keyframes miniBounce
{
    0% { transform: scaleY(0.2) translateZ(0); }
    100% { transform: scaleY(1) translateZ(0); }
}

.trackDetails
{
    flex: 1 1 0% !important;
    min-width: 0 !important;
    overflow: hidden !important;
    display: flex !important;
    flex-direction: column !important;
    justify-content: center !important;
}

.trackTitle
{
    font-size: 0.84rem !important;
    font-weight: 700 !important;
    white-space: nowrap !important;
    overflow: hidden !important;
    text-overflow: ellipsis !important;
    line-height: 1.25 !important;
    max-width: 100% !important;
}

.trackArtist
{
    font-size: 0.72rem !important;
    white-space: nowrap !important;
    overflow: hidden !important;
    text-overflow: ellipsis !important;
    line-height: 1.2 !important;
    max-width: 100% !important;
    opacity: 0.75;
}

.trackDuration
{
    font-size: 0.75rem !important;
    font-variant-numeric: tabular-nums !important;
    margin-left: auto !important;
    flex-shrink: 0 !important;
    white-space: nowrap !important;
    padding-left: 0.35rem !important;
}

.trackItemActions
{
    display: none !important;
    align-items: center !important;
    gap: 0.2rem !important;
    margin-left: auto !important;
    flex-shrink: 0 !important;
}

.trackItem:hover .trackItemActions,
.trackItem:focus-within .trackItemActions {
    display: flex !important;
}

.trackItem:hover .trackDuration,
.trackItem:focus-within .trackDuration {
    display: none !important;
}

.trackActionIconBtn
{
    all: unset;
    cursor: pointer;
    width: 1.55rem;
    height: 1.55rem;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border-radius: 0.28rem;
    background: rgba(255, 255, 255, 0.08);
    border: 1px solid rgba(255, 255, 255, 0.14);
    color: inherit;
    font-size: 0.75rem;
    font-weight: 700;
    transition: all 0.15s ease;
    box-sizing: border-box;
    line-height: 1;
}

.trackActionIconBtn:hover
{
    background: #00e5ff;
    color: #000000;
    border-color: #00e5ff;
    transform: scale(1.08);
}

.trackActionIconBtn.danger:hover
{
    background: #ff1744;
    color: #ffffff;
    border-color: #ff1744;
}

.trackMenuTriggerBtn
{
    all: unset;
    cursor: pointer;
    display: none;
    align-items: center;
    justify-content: center;
    width: 2.2rem;
    height: 2.2rem;
    min-width: 44px;
    min-height: 44px;
    border-radius: 0.35rem;
    color: inherit;
    opacity: 0.72;
    transition: opacity 0.15s ease, background-color 0.15s ease, transform 0.1s ease;
