/* ========================================================================= */
/* Soulseek Studio Workspace & Persistent Mini-Player Integration            */
/* ========================================================================= */

/* Workspace Switcher in Top Navigation Bar */
.workspaceSwitcher
{
    display: flex;
    align-items: center;
    background-color: #0c0c0c;
    border: 0.12rem solid #282828;
    border-radius: 0.4rem;
    padding: 0.2rem;
    gap: 0.25rem;
    margin-left: 0.5rem;
}

.wsTabBtn
{
    display: flex;
    align-items: center;
    gap: 0.45rem;
    background-color: #202020;
    border: 0.12rem solid #404040;
    color: #ffffff;
    padding: 0.4rem 0.95rem;
    font-size: 0.95rem;
    font-weight: 800;
    letter-spacing: 0.08rem;
    border-radius: 0.3rem;
    cursor: pointer;
    transition: background-color 0.1s ease, border-color 0.1s ease, color 0.1s ease, transform 0.08s ease;
    white-space: nowrap;
    touch-action: manipulation;
    user-select: none;
    -webkit-user-select: none;
    -webkit-tap-highlight-color: transparent;
}

.wsTabBtn .wsLabel
{
    color: #ffffff;
    font-weight: 800;
}

.wsTabBtn:hover
{
    color: #ffffff;
    background-color: #333333;
    border-color: #666666;
}

.wsTabBtn:active
{
    transform: scale(0.95);
    transition: transform 0.04s ease;
}

.wsTabBtn.active
{
    background-color: #000000;
    color: #ffffff !important;
    border-color: #ffffff;
    box-shadow: 0 0 14px rgba(255, 255, 255, 0.4);
    transform: scale(1.02);
}

.wsTabBtn.active .wsLabel
{
    color: inherit;
}

.wsTabBtn.active .wsIcon
{
    filter: none;
}

.wsBadge
{
    display: inline-block;
    font-size: 0.65rem;
    line-height: 1;
    color: #aaaaaa;
    transition: color 0.3s ease;
}

.wsBadge.online
{
    color: #00ff88;
