    50% { opacity: 0.3; }
}

/* Smooth Workspace Animations */
@keyframes wsFadeIn
{
    0%
    {
        opacity: 0;
        transform: translateY(8px);
    }
    100%
    {
        opacity: 1;
        transform: translateY(0);
    }
}

