    color: #ffffff;
    flex-shrink: 0;
    user-select: none;
}

.slskResultsHeader .col,
.slskResultsHeader .col span
{
    color: #ffffff;
    text-transform: uppercase;
    font-weight: 800;
}

.slskResultsHeader .col
{
    display: flex;
    align-items: center;
    gap: 0.4rem;
}

.slskResultsHeader .col.sortable
{
    cursor: pointer;
    transition: color 0.15s ease, background-color 0.15s ease;
    padding: 0.25rem 0.5rem;
    margin: -0.25rem -0.5rem;
    border-radius: 0.25rem;
    width: fit-content;
}

.slskResultsHeader .col.sortable:hover
{
    color: #ffffff;
    background-color: #2a2a2a;
}

.slskResultsHeader .col.sortable.active,
.slskResultsHeader .col.sortable.active span
{
    color: #00e5ff;
}

.slskResultsHeader .col.sortable .sortIndicator
{
    font-size: 0.75rem;
    color: #ffffff;
    opacity: 0.75;
    transition: opacity 0.2s, transform 0.2s;
}

.slskResultsHeader .col.sortable:hover .sortIndicator
{
    opacity: 1;
}

.slskResultsHeader .col.sortable.active .sortIndicator
{
    opacity: 1;
    color: #00e5ff;
}

.slskResultsList
{
    flex: 1;
    overflow-y: auto;
    overflow-x: hidden;
    display: flex;
    flex-direction: column;
}

.slskResultsList::-webkit-scrollbar
{
    width: 7px;
}

/* Individual Result Row */
.slskResultRow
{
    display: grid;
    grid-template-columns: 2.8fr 0.9fr 0.8fr 0.7fr 1.2fr 0.8fr 1.4fr;
    align-items: center;
    padding: 0.65rem 1rem;
    border-bottom: 0.08rem solid #161616;
    transition: background-color 0.15s ease;
    font-size: 0.88rem;
}

.slskResultRow:hover
{
    background-color: #121212;
}

.slskResultRow .colTrack
{
    display: flex;
    flex-direction: column;
    overflow: hidden;
    padding-right: 0.8rem;
}

.slskResultTitle
{
    color: #ffffff;
    font-weight: bold;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    font-size: 0.92rem;
}

.slskResultPath
{
    color: #ffffff;
    opacity: 0.92;
    font-size: 0.77rem;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    margin-top: 0.15rem;
}

.slskFormatBadge
{
    display: inline-block;
    padding: 0.15rem 0.45rem;
    border-radius: 0.2rem;
    font-size: 0.72rem;
    font-weight: bold;
    letter-spacing: 0.06rem;
    text-align: center;
    width: fit-content;
}

.slskFormatBadge.badgeFlac
{
    color: #00e5ff;
    background-color: rgba(0, 229, 255, 0.12);
    border: none;
}

.slskFormatBadge.badgeMp3
{
    color: #ffd700;
    background-color: rgba(255, 215, 0, 0.12);
    border: none;
}

.slskFormatBadge.badgeOther
{
    color: #ba68c8;
    background-color: rgba(186, 104, 200, 0.12);
    border: none;
}

.slskBitrateVal
{
    color: #ffffff;
    font-size: 0.84rem;
}

.slskBitrateVal.hiRes
{
    color: #00ff88;
    font-weight: bold;
}

.slskSampleRateVal
{
    display: block;
    color: #00e5ff !important;
    font-size: 0.72rem;
    font-weight: 700;
    letter-spacing: 0.04rem;
    margin-top: 0.15rem;
    white-space: nowrap;
}

.slskSizeVal
{
    color: #ffffff;
    font-size: 0.84rem;
}

.slskPeerVal
{
    display: flex;
    flex-direction: column;
    overflow: hidden;
}

.slskPeerUser
{
    color: #ffffff;
    font-size: 0.82rem;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.slskPeerSpeed
{
    color: #00ff88;
    font-size: 0.75rem;
    font-weight: bold;
}

.slskQueueVal
{
    font-size: 0.82rem;
    color: #ffffff;
}

.slskQueueVal.free
{
    color: #00ff88;
    font-weight: bold;
}

.slskQueueVal.queued
{
    color: #ffffff;
    font-weight: bold;
}

.slskActionCell
{
    display: flex;
    align-items: center;
    gap: 0.4rem;
}

.slskBtn
{
    background-color: #1b1b1b;
    border: 0.1rem solid #333333;
    color: #ffffff;
    padding: 0.35rem 0.65rem;
    border-radius: 0.25rem;
    font-size: 0.76rem;
    font-weight: bold;
    letter-spacing: 0.06rem;
    cursor: pointer;
    transition: all 0.15s ease;
    white-space: nowrap;
}

.slskBtn:hover
{
    background-color: #00e5ff;
    color: #000000;
    border-color: #00e5ff;
}

.slskBtnPrimary
{
    background-color: #00e5ff;
    color: #000000;
    border-color: #00e5ff;
}

.slskBtnPrimary:hover
{
    background-color: #ffffff;
    border-color: #ffffff;
    box-shadow: 0 0 10px rgba(0, 229, 255, 0.5);
}

.slskBtn.enqueued
{
    background-color: #183318;
    border-color: #00ff88;
    color: #00ff88;
    cursor: default;
}

/* Results Footer */
.slskResultsFooter
{
    display: flex;
    justify-content: space-between;
    align-items: center;
    background-color: #141414;
    border-top: 0.12rem solid #2a2a2a;
    padding: 0.55rem 1.4rem;
    font-size: 0.82rem;
    font-weight: 600;
    color: #ffffff;
    flex-shrink: 0;
}

.slskActiveSearchMeta
{
    color: #ffffff;
}

/* Placeholder / Radar Graphic */
.slskPlaceholder
{
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 4rem 2rem;
    gap: 1rem;
    text-align: center;
    margin: auto;
}

.slskRadarGraphic
{
    position: relative;
    width: 6rem;
    height: 6rem;
    border-radius: 50%;
    border: none;
    display: flex;
    align-items: center;
    justify-content: center;
    background: radial-gradient(circle, rgba(0, 229, 255, 0.05) 0%, transparent 70%);
}

.radarRing
{
    position: absolute;
    border-radius: 50%;
    border: 0.08rem dashed rgba(0, 229, 255, 0.2);
}

.radarRing.r1 { width: 3.8rem; height: 3.8rem; animation: gear 15s linear infinite; }
.radarRing.r2 { width: 5.2rem; height: 5.2rem; animation: gear 25s linear infinite reverse; }

.radarSweep
{
    position: absolute;
    width: 100%;
    height: 100%;
    border-radius: 50%;
    border-top: 0.15rem solid #00e5ff;
    animation: gear 3s linear infinite;
    opacity: 0.5;
}

.radarIcon
{
    font-size: 1.8rem;
    color: #00e5ff;
}

.slskPlaceholder h3
{
    color: #ffffff;
    font-size: 1.3rem;
    letter-spacing: 0.1rem;
}

.slskPlaceholder p
{
    color: #ffffff;
    max-width: 28rem;
    font-size: 0.95rem;
    line-height: 1.45;
}

.slskSampleTags
{
    display: flex;
    align-items: center;
    gap: 0.6rem;
    flex-wrap: wrap;
    justify-content: center;
    margin-top: 0.6rem;
}

.slskSampleTags span
{
    color: #ffffff;
    font-size: 0.85rem;
    font-weight: 600;
}

.sampleTagBtn
{
    background-color: #161616;
    border: 0.09rem solid #3a3a3a;
    color: #00e5ff;
    padding: 0.3rem 0.75rem;
    border-radius: 0.3rem;
    font-size: 0.82rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.2s;
}

.sampleTagBtn:hover
{
    background-color: #00e5ff;
    color: #000000;
    border-color: #00e5ff;
}

/* Searching Spinner State */
.slskSearchingState
{
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 4rem 2rem;
    gap: 1.2rem;
    text-align: center;
    margin: auto;
}

.slskSpinner
{
    width: 3.5rem;
    height: 3.5rem;
    border: 0.25rem solid rgba(0, 229, 255, 0.15);
    border-top-color: #00e5ff;
    border-radius: 50%;
    animation: spinTurntable 1s linear infinite;
}

.slskSearchingState h3
{
    color: #ffffff;
    font-size: 1.2rem;
    letter-spacing: 0.1rem;
}

.slskSearchingState p
{
    color: #ffffff;
    font-size: 0.88rem;
}

/* Transfers Drawer */
.slskTransfersDrawer
{
    position: absolute;
    bottom: 0;
    left: 1.8rem;
    right: 1.8rem;
    background-color: #0c0c0c;
    border: 0.12rem solid #2a2a2a;
    border-bottom: none;
    border-radius: 0.5rem 0.5rem 0 0;
    z-index: 15;
    transition: transform 0.3s cubic-bezier(0.16, 1, 0.3, 1);
    transform: translateY(calc(100% - 2.8rem));
    display: flex;
    flex-direction: column;
    box-shadow: 0 -8px 24px rgba(0, 0, 0, 0.6);
}

.slskTransfersDrawer.open
{
    transform: translateY(0);
}

.slskTransfersHeader
{
    display: flex;
    justify-content: space-between;
    align-items: center;
    height: 2.8rem;
    padding: 0 1.2rem;
    background-color: #141414;
    cursor: pointer;
    border-bottom: 0.08rem solid #222222;
    color: #ffffff !important;
}

.slskTransfersTitle,
.slskTransfersTitle strong,
.slskTransfersTitle .drawerArrow,
.slskTransfersTitle span,
.drawerArrow,
#slskDrawerArrow
{
    color: #ffffff !important;
}

.slskTransfersTitle
{
    display: flex;
    align-items: center;
    gap: 0.8rem;
    color: #ffffff !important;
    font-size: 0.92rem;
}

.slskTransfersTitle strong
{
    color: #ffffff !important;
    letter-spacing: 0.08rem;
    font-weight: 800;
}

.drawerArrow
{
    color: #ffffff !important;
    font-size: 0.8rem;
    transition: transform 0.3s ease;
}

.slskTransfersDrawer.open .drawerArrow
{
    transform: rotate(180deg);
}

.slskTransfersHeaderActions
{
    display: flex;
    align-items: center;
    gap: 0.6rem;
}

#slskResumeAllBtn
{
    background: rgba(56, 189, 248, 0.15) !important;
    border: 0.08rem solid rgba(56, 189, 248, 0.4) !important;
    color: #38bdf8 !important;
    height: 1.95rem !important;
    min-height: 1.95rem !important;
    padding: 0 0.75rem !important;
    font-size: 0.78rem !important;
    font-weight: 700 !important;
    letter-spacing: 0.04rem !important;
    border-radius: 0.35rem !important;
}

#slskResumeAllBtn:hover
{
    background: #38bdf8 !important;
    color: #000000 !important;
    border-color: #38bdf8 !important;
    box-shadow: 0 0 10px rgba(56, 189, 248, 0.45) !important;
}

/* SYNC ALL TO LIBRARY Button: High contrast resting state, luminous emerald hover */
#slskScanDownloadsBtn,
.slskTransfersHeaderActions #slskScanDownloadsBtn
{
    height: 1.95rem !important;
    min-height: 1.95rem !important;
    max-height: 1.95rem !important;
    box-sizing: border-box !important;
    background-color: rgba(0, 255, 136, 0.14) !important;
    border: 0.08rem solid rgba(0, 255, 136, 0.45) !important;
    color: #00ff88 !important;
    font-size: 0.78rem !important;
    font-weight: 700 !important;
    letter-spacing: 0.04rem !important;
    padding: 0 0.85rem !important;
    border-radius: 0.35rem !important;
    cursor: pointer !important;
    display: inline-flex !important;
    align-items: center !important;
    justify-content: center !important;
    text-align: center !important;
    white-space: nowrap !important;
    transition: all 0.2s ease !important;
    box-shadow: 0 0 8px rgba(0, 255, 136, 0.18) !important;
}

#slskScanDownloadsBtn *,
.slskTransfersHeaderActions #slskScanDownloadsBtn *
{
    color: #00ff88 !important;
}

#slskScanDownloadsBtn:hover,
.slskTransfersHeaderActions #slskScanDownloadsBtn:hover
{
    background-color: #00ff88 !important;
    border-color: #00ff88 !important;
    color: #000000 !important;
    box-shadow: 0 0 14px rgba(0, 255, 136, 0.5) !important;
}

#slskScanDownloadsBtn:hover *,
.slskTransfersHeaderActions #slskScanDownloadsBtn:hover *
{
    color: #000000 !important;
}

.slskTransfersHeader .closeBtn
{
    color: #dfeaf5 !important;
    background: rgba(255, 255, 255, 0.08) !important;
    border: 0.08rem solid rgba(255, 255, 255, 0.35) !important;
    border-radius: 0.3rem !important;
    font-size: 1.1rem;
    line-height: 1;
    padding: 0.2rem 0.45rem;
    display: inline-flex;
    align-items: center;
    justify-content: center;
}

.slskTransfersHeader .closeBtn:hover
{
    background: rgba(255, 255, 255, 0.16) !important;
    border-color: rgba(255, 255, 255, 0.7) !important;
    color: #ffffff !important;
}

.slskTransfersBody
{
    height: 14rem;
    overflow-y: auto;
    padding: 0.8rem 1.2rem;
    background-color: #080808;
}

.slskTransferRow
{
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.6rem 0.8rem;
    background-color: #111111;
    border: 0.08rem solid #222222;
    border-radius: 0.35rem;
    margin-bottom: 0.5rem;
    gap: 1rem;
}

.slskTransferLeft
{
    flex: 1;
    overflow: hidden;
}

.slskTransferName
{
    color: #ffffff;
    font-size: 0.88rem;
    font-weight: bold;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.slskTransferMeta
{
    display: flex;
    gap: 1rem;
    font-size: 0.78rem;
    color: #ffffff;
    margin-top: 0.25rem;
}

.slskTransferMeta span
{
    color: #ffffff;
}

.slskTransferMeta .speed
{
    color: #00ff88;
    font-weight: 600;
}

.slskTransferBarCon
{
    width: 14rem;
    height: 0.45rem;
    background-color: #222222;
    border-radius: 0.2rem;
    overflow: hidden;
    position: relative;
}

.slskTransferBarFill
{
    height: 100%;
    background-color: #00e5ff;
    width: 0%;
    transition: width 0.3s ease;
}

.slskTransferBarFill.finished
{
    background-color: #00ff88;
}

.slskTransferActions
{
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.slskPlayNowBtn
{
    background-color: #00ff88;
    color: #000000;
    border: none;
    font-weight: bold;
    padding: 0.35rem 0.8rem;
    border-radius: 0.25rem;
    cursor: pointer;
    font-size: 0.78rem;
    box-shadow: 0 0 8px rgba(0, 255, 136, 0.4);
    transition: transform 0.15s ease;
}

.slskPlayNowBtn:hover
{
    transform: scale(1.05);
}

.slskTransferBtn
{
    background-color: #161616;
    border: 0.08rem solid #333333;
    color: #ffffff;
    font-size: 0.74rem;
    font-weight: bold;
    padding: 0.3rem 0.65rem;
    border-radius: 0.25rem;
    cursor: pointer;
    transition: all 0.15s ease;
    white-space: nowrap;
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
}

.slskTransferBtn:hover
{
    background-color: #262626;
    border-color: #666666;
}

.slskPauseBtn
{
    color: #ffcc00 !important;
    border-color: rgba(255, 204, 0, 0.4);
}

.slskPauseBtn:hover
{
    background-color: #ffcc00;
    color: #000000 !important;
    border-color: #ffcc00;
}

.slskResumeBtn
{
    color: #00ff88 !important;
    border-color: rgba(0, 255, 136, 0.4);
}

.slskResumeBtn:hover
{
    background-color: #00ff88;
    color: #000000 !important;
    border-color: #00ff88;
}

.slskCancelBtn
{
    color: #ff4d4d !important;
    border-color: rgba(255, 77, 77, 0.4);
}

.slskCancelBtn:hover
{
    background-color: #ff4d4d;
    color: #000000 !important;
    border-color: #ff4d4d;
}

.slskEmptyTransfers
{
    display: flex;
    align-items: center;
    justify-content: center;
    height: 100%;
    color: #ffffff;
    font-size: 0.9rem;
}

/* ========================================================================= */
/* Persistent Mini-Player Bar                                                */
/* ========================================================================= */
.persistentMiniPlayer
{
    position: fixed;
    bottom: 0;
    left: 0;
    right: 0;
    height: 4.8rem;
    background-color: rgba(6, 6, 6, 0.96);
    backdrop-filter: blur(14px);
    border-top: 0.12rem solid #222222;
    display: none;
    align-items: center;
    justify-content: space-between;
    padding: 0 2rem;
    z-index: 30;
    box-shadow: 0 -4px 20px rgba(0, 0, 0, 0.7);
}

.miniPlayerLeft
{
    display: flex;
    align-items: center;
    gap: 1rem;
    width: 22rem;
    max-width: 30vw;
    overflow: hidden;
}

.miniTurntableThumb
{
    position: relative;
    width: 3.2rem;
    height: 3.2rem;
    border-radius: 50%;
    background-color: #000000;
    border: 0.1rem solid #333333;
    overflow: hidden;
    flex-shrink: 0;
    display: flex;
    align-items: center;
    justify-content: center;
}

.miniTurntableThumb img
{
    width: 100%;
    height: 100%;
    object-fit: cover;
    border-radius: 50%;
}

.miniTurntableThumb.playing img
{
    animation: spinTurntable 3.5s linear infinite;
}

.miniSpindle
{
    position: absolute;
    width: 0.5rem;
    height: 0.5rem;
    border-radius: 50%;
    background-color: #ffffff;
    box-shadow: 0 0 4px rgba(0, 0, 0, 0.8);
}

.miniTrackInfo
{
    display: flex;
    flex-direction: column;
    overflow: hidden;
}

.miniTitle
{
    color: #ffffff;
    font-weight: bold;
    font-size: 0.95rem;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.miniArtist
{
    color: #ffffff;
    opacity: 0.85;
    font-size: 0.8rem;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    margin-top: 0.1rem;
}

.miniPlayerCenter
{
    display: flex;
    flex-direction: column;
    align-items: center;
    flex: 1;
    max-width: 40rem;
    gap: 0.3rem;
}

.miniControls
{
    display: flex;
    align-items: center;
    gap: 0.8rem;
}

.miniBtn
{
    background: none;
    border: none;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 0.3rem;
    transition: transform 0.15s ease;
}

.miniBtn:hover
{
    transform: scale(1.12);
}

.miniBtn img
{
    width: 1.4rem;
    height: 1.4rem;
    filter: invert(1);
}

.miniPlayBtn
{
    background-color: #ffffff;
    border-radius: 50%;
    width: 2.2rem;
    height: 2.2rem;
    box-shadow: 0 0 10px rgba(255, 255, 255, 0.3);
    color: #000000 !important;
}

.miniPlayBtn svg,
.miniPlayBtn svg path
{
    fill: #000000 !important;
    color: #000000 !important;
}

.miniPlayBtn:hover
{
    transform: scale(1.08);
}

.miniPlayBtn img
{
    filter: invert(0);
    width: 1.1rem;
    height: 1.1rem;
}

.miniScrubberRow
{
    display: flex;
    align-items: center;
    width: 100%;
    gap: 0.8rem;
}

.miniTime
{
    color: #ffffff;
    opacity: 0.9;
    font-size: 0.72rem;
    font-family: monospace;
    width: 2.5rem;
    text-align: center;
}

.miniProgressBarCon
{
    flex: 1;
    height: 0.35rem;
    background-color: #222222;
    border-radius: 0.2rem;
    cursor: pointer;
    overflow: hidden;
    position: relative;
}

.miniProgressBar
{
    height: 100%;
    background-color: #ffffff;
    width: 0%;
    border-radius: 0.2rem;
    transition: width 0.1s linear;
}

.miniProgressBarCon:hover .miniProgressBar
{
    background-color: #00e5ff;
}

.miniPlayerRight
{
    display: flex;
    align-items: center;
    gap: 1.2rem;
    width: 22rem;
    max-width: 30vw;
    justify-content: flex-end;
}

.miniVolumeCon
{
    display: flex;
    align-items: center;
    gap: 0.6rem;
}

.miniMuteBtn
{
    background: none;
    border: none;
    cursor: pointer;
    display: flex;
    align-items: center;
    color: #ffffff !important;
    padding: 0.2rem;
    transition: color 0.15s ease, transform 0.15s ease;
}

.miniMuteBtn svg,
.miniMuteBtn svg path,
#miniVolumeIcon,
#miniVolumeIcon path
{
    fill: #ffffff !important;
    color: #ffffff !important;
    transition: fill 0.15s ease;
}

.miniMuteBtn:hover
{
    color: #00e5ff !important;
    transform: scale(1.15);
}

.miniMuteBtn:hover svg,
.miniMuteBtn:hover svg path,
.miniMuteBtn:hover #miniVolumeIcon,
.miniMuteBtn:hover #miniVolumeIcon path
{
    fill: #00e5ff !important;
    color: #00e5ff !important;
}

/* Highly visible volume slider and knob on Soulseek dark bar */
.persistentMiniPlayer .volumeSlider,
#miniVolumeSlider
{
    -webkit-appearance: none;
    appearance: none;
    width: 6.8rem;
    height: 0.4rem;
    background: #444444 !important;
    border-radius: 0.25rem;
    outline: none;
    cursor: pointer;
    transition: background 0.15s ease;
}

.persistentMiniPlayer .volumeSlider:hover,
#miniVolumeSlider:hover
{
    background: #555555 !important;
