    border-radius: 50%;
    background: var(--accent-color, #00f0ff);
    margin-top: 0.35rem;
    flex-shrink: 0;
    box-shadow: 0 0 6px var(--accent-glow, rgba(0, 240, 255, 0.5));
}

.featureItem strong
{
    display: block;
    font-size: 0.85rem;
    color: #ffffff;
    margin-bottom: 0.2rem;
}

.featureItem p
{
    margin: 0;
    font-size: 0.8rem;
    color: #9ca3af;
    line-height: 1.4;
}

/* Actions Row */
.cardActionsRow
{
    display: flex;
    gap: 0.8rem;
    align-items: center;
    flex-wrap: wrap;
    margin-top: 0.3rem;
}

.cardActionsRow .actionBtn,
.downloadOptionsRow .actionBtn
{
    height: 2.3rem !important;
    padding: 0 1.15rem !important;
    font-size: 0.8rem !important;
    font-weight: 700 !important;
    letter-spacing: 0.04rem !important;
    text-decoration: none !important;
    border-radius: 0.35rem !important;
    display: inline-flex !important;
    align-items: center !important;
    justify-content: center !important;
}

/* Options Grid for Windows & Mac */
.downloadOptionsRow
{
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: 1.2rem;
}

.optionBox
{
    background: #111116;
    border: 1px solid #282832;
    border-radius: 0.5rem;
    padding: 1.25rem;
    display: flex;
    flex-direction: column;
    gap: 0.65rem;
}

.optionBadge
{
    display: inline-block;
    align-self: flex-start;
    font-size: 0.65rem;
    font-weight: 800;
    letter-spacing: 0.08rem;
    color: var(--accent-color, #00f0ff);
    background: rgba(0, 240, 255, 0.08);
    border: none;
    padding: 0.15rem 0.5rem;
    border-radius: 0.25rem;
}

.optionBox h4
{
    margin: 0;
    font-size: 1.05rem;
    color: #ffffff;
}

.optionBox p
{
    margin: 0;
    font-size: 0.84rem;
    color: #a1a1aa;
    line-height: 1.45;
    flex: 1;
}

/* LAN Card */
.lanAddressCard
{
    background: #0f131a;
    border: 1.5px solid rgba(0, 240, 255, 0.35);
    border-radius: 0.55rem;
    padding: 1.35rem;
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
    box-shadow: 0 0 15px rgba(0, 240, 255, 0.08);
}

.lanAddressLabel
{
    font-size: 0.75rem;
    font-weight: 800;
    letter-spacing: 0.08rem;
    color: var(--accent-color, #00f0ff);
}

.lanAddressRow
{
    display: flex;
    gap: 0.75rem;
    align-items: stretch;
    flex-wrap: wrap;
}

.lanUrlInput
{
    background: #05070a;
    border: 1px solid #2b3245;
    color: #00f0ff;
    font-family: monospace;
    font-size: 1.1rem;
    font-weight: 800;
    padding: 0.65rem 1rem;
    border-radius: 0.35rem;
    flex: 1;
    min-width: 250px;
    outline: none;
    box-shadow: inset 0 2px 4px rgba(0, 0, 0, 0.8);
}

.lanAddressHelp
{
    margin: 0;
    font-size: 0.82rem;
    color: #94a3b8;
    line-height: 1.4;
}

/* Mobile Steps Grid */
.mobileStepsGrid
{
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: 1.2rem;
}

.mobileStepCard
{
    background: #111116;
    border: 1px solid #25252f;
    border-radius: 0.5rem;
    padding: 1.3rem;
}

.mobileStepCard h4
{
    margin: 0 0 0.6rem 0;
    font-size: 1.05rem;
    color: #ffffff;
}

.mobileStepCard ol
{
    margin: 0;
    padding-left: 1.25rem;
    color: #d4d4d8;
    font-size: 0.84rem;
    line-height: 1.6;
}

.mobileStepCard li
{
    margin-bottom: 0.4rem;
}

/* Direct PWA Card */
.pwaHeroAction
{
    background: #111116;
    border: 1px solid #262630;
    border-radius: 0.5rem;
    padding: 2.2rem;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    text-align: center;
    gap: 1rem;
}

.pwaBigInstallBtn
{
    height: 2.8rem !important;
    padding: 0 2rem !important;
    font-size: 0.95rem !important;
    font-weight: 800 !important;
    letter-spacing: 0.06rem !important;
    box-shadow: 0 0 16px rgba(0, 229, 255, 0.45) !important;
}

.pwaInstallHint
{
    margin: 0;
    font-size: 0.85rem;
    color: #a1a1aa;
}

@media (max-width: 1100px) and (min-width: 769px) and (min-height: 521px)
{
    .downloadTabsBar
    {
        grid-template-columns: repeat(3, 1fr);
    }
}

/* Mobile Responsiveness for Download Workspace */
@media (max-width: 768px)
{
    .downloadWorkspace
    {
        padding: 1rem;
        gap: 1.1rem;
        margin-bottom: 4rem;
    }

    .downloadHubHeader
    {
        flex-direction: column;
        align-items: stretch;
    }

    .downloadHubHeaderRight
    {
        width: 100%;
        justify-content: flex-start;
    }

    .downloadTabsBar
    {
        display: grid;
        grid-template-columns: repeat(2, 1fr);
        gap: 0.65rem;
        border-bottom: 0.12rem solid #26262f;
        padding-bottom: 0.85rem;
        width: 100%;
        box-sizing: border-box;
    }

    .downloadTabBtn
    {
        min-height: 3.8rem;
        padding: 0.65rem 0.85rem;
        width: 100%;
        box-sizing: border-box;
    }

    .downloadTabBtn[data-platform="pwa"]
    {
        grid-column: span 2;
    }

    .downloadCardMain
    {
        padding: 1.2rem;
    }

    .featureGrid,
    .downloadOptionsRow,
    .mobileStepsGrid
    {
        grid-template-columns: 1fr;
    }

    .pwaHeroAction
    {
        padding: 1.4rem;
    }

    .pwaBigInstallBtn
    {
        width: 100%;
    }
}

/* =========================================================================
   DEDICATED STUDIO SETTINGS & PREFERENCES WORKSPACE
   ========================================================================= */

.settingsWorkspace
{
    display: none;
    flex-direction: column;
    flex: 1;
    height: auto;
    min-height: 0;
    margin-bottom: 4.4rem;
    background-color: var(--bg-base, #070912);
    color: var(--text-primary, #ffffff);
    position: relative;
    z-index: 5;
    overflow-y: auto;
    overscroll-behavior: contain;
    padding: 1.8rem 2.2rem;
    gap: 1.6rem;
    box-sizing: border-box;
}

.settingsHubHeader
{
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    gap: 1.5rem;
    padding-bottom: 1.4rem;
    border-bottom: 0.1rem solid var(--border-color, #222226);
    flex-wrap: wrap;
}

.settingsHubHeaderLeft
{
    display: flex;
    flex-direction: column;
    gap: 0.35rem;
}

.settingsBadge
{
    display: inline-flex;
    align-self: flex-start;
    font-size: 0.72rem;
    font-weight: 800;
    letter-spacing: 0.12rem;
    color: var(--accent-color, #00f0ff);
    background: rgba(0, 240, 255, 0.08);
    border: none;
    padding: 0.22rem 0.65rem;
    border-radius: 0.3rem;
    text-shadow: 0 0 6px var(--accent-glow, rgba(0, 240, 255, 0.4));
}

.settingsHubHeaderLeft h2
{
    margin: 0;
    font-size: 1.55rem;
    letter-spacing: 0.08rem;
    color: var(--text-primary, #ffffff);
    font-weight: 800;
}

.settingsSubtitle
{
    margin: 0;
    font-size: 0.88rem;
    color: var(--text-secondary, #a1a1aa);
    max-width: 780px;
    line-height: 1.5;
}

.settingsHubHeaderRight
{
    display: flex;
    gap: 0.85rem;
    align-items: center;
    flex-wrap: wrap;
}

.settingsReturnBtn
{
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid var(--border-color, rgba(255, 255, 255, 0.16));
    color: var(--text-primary, #ffffff);
    padding: 0.6rem 1.1rem;
    font-size: 0.82rem;
    font-weight: 700;
    letter-spacing: 0.06rem;
    border-radius: 0.4rem;
    cursor: pointer;
    transition: all 0.2s ease;
}

.settingsReturnBtn:hover
{
    background: var(--accent-color, #00f0ff);
    color: #000000;
    border-color: var(--accent-color, #00f0ff);
    box-shadow: 0 0 16px var(--accent-glow, rgba(0, 240, 255, 0.4));
}

/* Balanced 2-Column Studio Grid Layout */
.settingsLayoutGrid {
    display: grid;
    grid-template-columns: 1.05fr 0.95fr;
    gap: 1.6rem;
    align-items: start;
    width: 100%;
    box-sizing: border-box;
}

.settingsCol {
    display: flex;
    flex-direction: column;
    gap: 1.6rem;
    width: 100%;
    box-sizing: border-box;
}

/* Unified Studio Section Panel (replaces fragmented cards) */
.settingsSectionPanel {
    display: flex;
    flex-direction: column;
    gap: 1.3rem;
    padding: 1.6rem 1.7rem;
    background: var(--bg-surface, rgba(16, 18, 27, 0.82));
    border: 1px solid var(--border-color, rgba(255, 255, 255, 0.12));
    border-radius: 0.75rem;
    backdrop-filter: blur(16px);
    -webkit-backdrop-filter: blur(16px);
    box-shadow: 0 8px 30px rgba(0, 0, 0, 0.35);
    box-sizing: border-box;
    transition: border-color 0.22s ease, box-shadow 0.22s ease;
}

.settingsSectionPanel:hover {
    border-color: rgba(255, 255, 255, 0.2);
    box-shadow: 0 10px 34px rgba(0, 0, 0, 0.45);
}

.settingsSectionHeader {
    display: flex;
    flex-direction: column;
    gap: 0.4rem;
    padding-bottom: 0.95rem;
    border-bottom: 1px solid var(--border-color, rgba(255, 255, 255, 0.1));
}

.settingsSectionTitleRow {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    flex-wrap: wrap;
}

.settingsSectionBadge {
    display: inline-flex;
    align-items: center;
    font-size: 0.68rem;
    font-weight: 800;
    letter-spacing: 0.12em;
    padding: 0.22rem 0.55rem;
    border-radius: 0.3rem;
    background: rgba(255, 255, 255, 0.08);
    color: var(--accent-color, #00f0ff);
    border: 1px solid rgba(255, 255, 255, 0.15);
    text-transform: uppercase;
}

.settingsSectionTitle {
    margin: 0;
    font-size: 1.15rem;
    font-weight: 800;
    letter-spacing: 0.06em;
    color: var(--text-primary, #ffffff);
}

.settingsSectionDesc {
    margin: 0;
    font-size: 0.84rem;
    color: var(--text-secondary, #cbd5e1);
    line-height: 1.45;
}

/* Panel Content and Unified Rows */
.settingsPanelContent {
    display: flex;
    flex-direction: column;
    gap: 1.3rem;
    width: 100%;
    box-sizing: border-box;
}

.settingsRowItem {
    display: flex;
    flex-direction: column;
    gap: 0.85rem;
    padding-bottom: 1.25rem;
    border-bottom: 1px solid var(--border-color, rgba(255, 255, 255, 0.08));
    width: 100%;
    box-sizing: border-box;
}

.settingsRowItem:last-child {
    border-bottom: none;
    padding-bottom: 0;
}

.settingsRowHeader {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    gap: 1rem;
    flex-wrap: wrap;
}

.settingsRowTitleGroup {
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
    flex: 1 1 240px;
}

.settingsRowTitle {
    margin: 0;
    font-size: 0.92rem;
    font-weight: 800;
    letter-spacing: 0.05em;
    color: var(--text-primary, #ffffff);
}

.settingsRowDesc {
    margin: 0;
    font-size: 0.8rem;
    line-height: 1.42;
    color: var(--text-secondary, #94a3b8);
}

/* Control Pills & Status Badges */
.settingsEnginePill {
    font-size: 0.7rem;
    font-weight: 800;
    letter-spacing: 0.06em;
    padding: 0.24rem 0.65rem;
    border-radius: 0.35rem;
    background: rgba(255, 255, 255, 0.08);
    color: var(--accent-color, #00f0ff);
    border: 1px solid rgba(255, 255, 255, 0.16);
    white-space: nowrap;
    align-self: flex-start;
}

.settingsThemeBadge {
    font-size: 0.74rem;
    font-weight: 800;
    letter-spacing: 0.08rem;
    padding: 0.25rem 0.65rem;
    border-radius: 0.35rem;
    background: var(--accent-color, #00f0ff);
    color: #000000;
    box-shadow: 0 0 10px var(--accent-glow, rgba(0, 240, 255, 0.35));
    white-space: nowrap;
    align-self: flex-start;
}

.settingsSleepBadge {
    font-size: 0.72rem;
    font-weight: 800;
    letter-spacing: 0.08rem;
    padding: 0.24rem 0.65rem;
    border-radius: 0.35rem;
    background: rgba(255, 255, 255, 0.1);
    color: var(--text-secondary, #94a3b8);
    transition: all 0.2s ease;
    white-space: nowrap;
    align-self: flex-start;
}

.settingsSleepBadge.active {
    background: #00ff88;
    color: #000000;
    box-shadow: 0 0 10px rgba(0, 255, 136, 0.4);
}

/* Option Toggles & Segmented Buttons */
.settingsOptionToggles {
    display: flex;
    gap: 0.55rem;
    flex-wrap: wrap;
    align-items: center;
}

.settingsOptionToggles .actionBtn,
.enginePrecisionBtn,
.ditherModeBtn,
.bufferLatencyBtn {
    font-size: 0.76rem;
    font-weight: 700;
    letter-spacing: 0.04em;
    padding: 0.5rem 0.95rem;
    border-radius: 0.4rem;
    border: 1px solid var(--border-color, rgba(255, 255, 255, 0.16));
    background: rgba(255, 255, 255, 0.05);
    color: var(--text-primary, #ffffff);
    cursor: pointer;
    transition: all 0.18s ease;
    text-align: center;
    box-shadow: none;
}

.settingsOptionToggles .actionBtn:hover,
.enginePrecisionBtn:hover,
.ditherModeBtn:hover,
.bufferLatencyBtn:hover {
    background: rgba(255, 255, 255, 0.12);
    border-color: var(--accent-color, #00f0ff);
    color: var(--accent-color, #00f0ff);
}

.settingsOptionToggles .actionBtn.active,
.enginePrecisionBtn.active,
.ditherModeBtn.active,
.bufferLatencyBtn.active {
    background: var(--accent-color, #00f0ff) !important;
    border-color: var(--accent-color, #00f0ff) !important;
    color: var(--text-on-accent, #000000) !important;
    font-weight: 800 !important;
    box-shadow: 0 0 12px var(--accent-glow, rgba(0, 240, 255, 0.35)) !important;
}

/* Toggle Active Button (Hardware Gain, Ultrasonic, Ambiophonics) */
.toggleActiveBtn {
    display: inline-flex;
    align-items: center;
    gap: 0.55rem;
    font-size: 0.78rem;
    font-weight: 800;
    padding: 0.55rem 1.05rem;
    border-radius: 0.4rem;
    cursor: pointer;
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid var(--border-color, rgba(255, 255, 255, 0.18));
    color: var(--text-primary, #ffffff);
    transition: all 0.2s ease;
}

.toggleActiveBtn.active {
    background: var(--accent-surface, rgba(0, 255, 136, 0.12)) !important;
    border-color: var(--accent-color, #00ff88) !important;
    color: var(--accent-color, #00ff88) !important;
    box-shadow: 0 0 12px var(--accent-glow, rgba(0, 255, 136, 0.25)) !important;
}

:is([data-theme="brutalist-light"], [data-theme="minimalist-light"]) .toggleActiveBtn.active {
    background: #000000 !important;
    border-color: #000000 !important;
    color: #ffffff !important;
    box-shadow: none !important;
}

[data-theme="minimalist-warm"] .toggleActiveBtn.active {
    background: #1c1917 !important;
    border-color: #d97706 !important;
    color: #ffffff !important;
    box-shadow: none !important;
}

/* Select Dropdown */
.settingsSelect {
    font-size: 0.78rem;
    font-weight: 700;
    padding: 0.5rem 0.85rem;
    border-radius: 0.4rem;
    background: rgba(0, 0, 0, 0.45);
    border: 1px solid var(--border-color, rgba(255, 255, 255, 0.2));
    color: var(--text-primary, #ffffff);
    outline: none;
    cursor: pointer;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

.settingsSelect:focus {
    border-color: var(--accent-color, #00f0ff);
    box-shadow: 0 0 8px var(--accent-glow, rgba(0, 240, 255, 0.3));
}

.settingsInlineControls {
    display: flex;
    align-items: center;
    gap: 0.65rem;
    flex-wrap: wrap;
}

/* DSP Metrics Grid */
.settingsDspMetricsGrid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 0.65rem;
}

.settingsDspMetricItem {
    display: flex;
    flex-direction: column;
    gap: 0.2rem;
    padding: 0.65rem 0.85rem;
    background: rgba(0, 0, 0, 0.3);
    border: 1px solid var(--border-color, rgba(255, 255, 255, 0.08));
    border-radius: 0.45rem;
}

.settingsDspKey {
    font-size: 0.68rem;
    font-weight: 800;
    letter-spacing: 0.08rem;
    color: var(--text-secondary, #94a3b8);
}

.settingsDspVal {
    font-size: 0.84rem;
    font-weight: 800;
    color: var(--text-primary, #ffffff);
    font-family: monospace;
    white-space: normal;
    word-break: break-word;
    overflow-wrap: anywhere;
}

/* Theme Quick Grid */
.settingsThemeQuickGrid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(130px, 1fr));
    gap: 0.45rem;
}

.themeQuickBtn {
    font-size: 0.74rem;
    font-weight: 700;
    letter-spacing: 0.04rem;
    padding: 0.5rem 0.65rem;
    border-radius: 0.4rem;
    text-align: center;
    justify-content: center;
    border: 1px solid var(--border-color, rgba(255, 255, 255, 0.14));
    background: rgba(255, 255, 255, 0.04);
    color: var(--text-primary, #ffffff);
    cursor: pointer;
    transition: all 0.18s ease;
}

.themeQuickBtn:hover {
    background: rgba(255, 255, 255, 0.12);
    border-color: var(--accent-color, #00f0ff);
    color: var(--accent-color, #00f0ff);
}

.themeQuickBtn.active {
    background: var(--accent-color, #00f0ff);
    border-color: var(--accent-color, #00f0ff);
    color: #000000;
    font-weight: 800;
    box-shadow: 0 0 12px var(--accent-glow, rgba(0, 240, 255, 0.35));
}

/* Visualizer Mode Selector Grid */
.visSelectorGrid {
    display: flex;
    gap: 0.55rem;
    flex-wrap: wrap;
}

.visModeBtn {
    font-size: 0.76rem;
    font-weight: 700;
    letter-spacing: 0.04em;
    padding: 0.5rem 0.95rem;
    border-radius: 0.4rem;
    border: 1px solid var(--border-color, rgba(255, 255, 255, 0.14));
    background: rgba(255, 255, 255, 0.04);
    color: var(--text-primary, #ffffff);
    cursor: pointer;
    transition: all 0.18s ease;
}

.visModeBtn:hover {
    background: rgba(255, 255, 255, 0.12);
    border-color: var(--accent-color, #00f0ff);
    color: var(--accent-color, #00f0ff);
}

.visModeBtn.active {
    background: var(--accent-color, #00f0ff);
    border-color: var(--accent-color, #00f0ff);
    color: #000000;
    font-weight: 800;
    box-shadow: 0 0 12px var(--accent-glow, rgba(0, 240, 255, 0.35));
}

.settingsCardNote {
    margin: 0;
    font-size: 0.78rem;
    line-height: 1.45;
    color: var(--text-secondary, #94a3b8);
    font-style: italic;
}

/* Folder Scanner & Inputs */
.settingsFolderInputRow {
    display: flex;
    gap: 0.55rem;
    flex-wrap: wrap;
}

.settingsInput {
    flex: 1 1 200px;
    background: rgba(0, 0, 0, 0.35);
    border: 1px solid var(--border-color, rgba(255, 255, 255, 0.2));
    border-radius: 0.4rem;
    padding: 0.6rem 0.85rem;
    color: var(--text-primary, #ffffff);
    font-family: inherit;
    font-size: 0.82rem;
    outline: none;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

.settingsInput:focus {
    border-color: var(--accent-color, #00f0ff);
    box-shadow: 0 0 8px var(--accent-glow, rgba(0, 240, 255, 0.3));
}

.settingsPresetsRow {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    flex-wrap: wrap;
}

.settingsPresetLabel {
    font-size: 0.72rem;
    font-weight: 800;
    letter-spacing: 0.08rem;
    color: var(--text-secondary, #94a3b8);
}

.presetPathBtn {
    font-size: 0.74rem;
    font-weight: 700;
    padding: 0.3rem 0.65rem;
    background: rgba(255, 255, 255, 0.06);
    border: 1px solid var(--border-color, rgba(255, 255, 255, 0.14));
    border-radius: 0.35rem;
    color: var(--text-primary, #ffffff);
    cursor: pointer;
    transition: all 0.18s ease;
}

.presetPathBtn:hover {
    background: var(--accent-color, #00f0ff);
    color: #000000;
    border-color: var(--accent-color, #00f0ff);
}

.settingsScanStatusBox {
    font-size: 0.78rem;
    padding: 0.6rem 0.85rem;
    background: rgba(0, 0, 0, 0.35);
    border-radius: 0.4rem;
    border-left: 3px solid var(--accent-color, #00f0ff);
    color: var(--accent-color, #00f0ff);
    font-family: monospace;
}

/* Sleep Quick Presets */
.settingsSleepQuickRow {
    display: flex;
    gap: 0.5rem;
    flex-wrap: wrap;
}

.settingsSleepPresetBtn {
    font-size: 0.74rem;
    font-weight: 700;
    padding: 0.45rem 0.75rem;
    border-radius: 0.38rem;
}

.settingsDownloadQuickRow {
    display: flex;
    gap: 0.75rem;
    flex-wrap: wrap;
}

.settingsFullWidthBtn {
    width: 100%;
    padding: 0.72rem 1.1rem;
    font-size: 0.82rem;
