@keyframes nmsVisorScan {
    0% {
        top: 0%;
        opacity: 0.85;
    }
    50% {
        opacity: 1;
    }
    100% {
        top: calc(100% - 2px);
        opacity: 0.85;
    }
}

@keyframes atlasCorePulse {
    0%, 100% {
        transform: translateY(-50%) rotate(45deg) scale(1);
        box-shadow: 0 0 8px rgba(255, 42, 85, 0.5), 0 2px 6px rgba(0, 0, 0, 0.6);
    }
    50% {
        transform: translateY(-50%) rotate(45deg) scale(1.08);
        box-shadow: 0 0 12px rgba(255, 42, 85, 0.7), 0 2px 8px rgba(0, 0, 0, 0.7);
    }
}

@keyframes atlasPlayPulse {
    0%, 100% {
        box-shadow: 0 4px 18px rgba(0, 0, 0, 0.6), 0 0 20px rgba(225, 29, 72, 0.35), inset 0 1px 2px rgba(255, 255, 255, 0.5);
    }
    50% {
        box-shadow: 0 4px 20px rgba(0, 0, 0, 0.65), 0 0 24px rgba(225, 29, 72, 0.45), inset 0 1px 2px rgba(255, 255, 255, 0.55);
    }
}

