   Space-saving 5px width/height, invisible transparent tracks,
   and floating rounded pill thumbs tinted distinctly per theme
   ========================================================================== */

/* Universal Scrollbar Dimensions & Invisible Track */
::-webkit-scrollbar {
    width: 8px !important;
    height: 8px !important;
}

::-webkit-scrollbar-corner {
    background: transparent !important;
}

::-webkit-scrollbar-track {
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
}

::-webkit-scrollbar-track:hover {
    background: rgba(128, 128, 128, 0.08) !important;
    border-radius: 9999px !important;
}

::-webkit-scrollbar-thumb {
    min-height: 40px !important;
    min-width: 40px !important;
    border-radius: 9999px !important;
    transition: background 0.15s ease, box-shadow 0.15s ease !important;
}

/* 1. DEFAULT THEME: Minimalist Translucent Dark Pill */
:root:not([data-theme]),
:root:not([data-theme]) *,
:root[data-theme="default"],
:root[data-theme="default"] *,
[data-theme="default"],
[data-theme="default"] * {
    scrollbar-color: rgba(24, 24, 27, 0.45) transparent !important;
    scrollbar-width: thin !important;
}

:root:not([data-theme]) ::-webkit-scrollbar-thumb,
:root:not([data-theme]) *::-webkit-scrollbar-thumb,
:root[data-theme="default"] ::-webkit-scrollbar-thumb,
:root[data-theme="default"] *::-webkit-scrollbar-thumb,
[data-theme="default"] ::-webkit-scrollbar-thumb,
[data-theme="default"] *::-webkit-scrollbar-thumb {
    background: rgba(24, 24, 27, 0.45) !important;
    border-radius: 9999px !important;
    border: none !important;
    box-shadow: none !important;
}

:root:not([data-theme]) ::-webkit-scrollbar-thumb:hover,
:root:not([data-theme]) *::-webkit-scrollbar-thumb:hover,
:root[data-theme="default"] ::-webkit-scrollbar-thumb:hover,
:root[data-theme="default"] *::-webkit-scrollbar-thumb:hover,
[data-theme="default"] ::-webkit-scrollbar-thumb:hover,
[data-theme="default"] *::-webkit-scrollbar-thumb:hover,
:root:not([data-theme]) ::-webkit-scrollbar-thumb:active,
:root:not([data-theme]) *::-webkit-scrollbar-thumb:active,
:root[data-theme="default"] ::-webkit-scrollbar-thumb:active,
:root[data-theme="default"] *::-webkit-scrollbar-thumb:active,
[data-theme="default"] ::-webkit-scrollbar-thumb:active,
