/* =========================================================================
   CROSS-BROWSER HARDWARE ACCELERATION & COMPOSITOR OPTIMIZATION
   Optimizes layout boundaries and frame compositing across Chromium & Firefox
   ========================================================================= */

/* Dedicated GPU compositing layer boundaries */
.turntableCon {
    overflow: visible !important;
    transform: translateZ(0);
}

.vinylTurntable {
    will-change: transform;
    transform: translateZ(0);
    backface-visibility: hidden;
}

.turntableCenterVis {
    will-change: transform;
    transform: translate3d(-50%, -50%, 0);
    backface-visibility: hidden;
}

.turntableCenterCanvas {
    transform: translateZ(0);
    backface-visibility: hidden;
}

.visualizerDock {
    contain: layout paint;
    transform: translateZ(0);
    backface-visibility: hidden;
}

#visualizerCanvas {
    contain: strict;
    transform: translateZ(0);
    backface-visibility: hidden;
}

/* Firefox-Specific WebRender Compositor Tuning:
   Completely bypasses expensive multi-pass framebuffer backdrop blur copies across ALL themes and panels,
   substituting high-contrast translucent surfaces to maintain fluid 60-144 FPS in Gecko */
html.is-firefox *,
html.is-firefox *::before,
html.is-firefox *::after {
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
}

html.is-firefox .ambientAuraGlow {
    filter: none !important;
    animation: none !important;
}

html.is-firefox .deckArtworkAmbient {
    filter: blur(8px) !important;
}

html.is-firefox:not(:is(:is([data-theme="brutalist-light"], [data-theme="minimalist-light"]), [data-theme="minimalist-light"], [data-theme="minimalist-warm"])) .topBar {
    background: rgba(14, 14, 18, 0.96) !important;
}

html.is-firefox:not(:is(:is([data-theme="brutalist-light"], [data-theme="minimalist-light"]), [data-theme="minimalist-light"], [data-theme="minimalist-warm"])) #mobileTabBar {
    background: rgba(14, 14, 18, 0.97) !important;
}

html.is-firefox:not(:is(:is([data-theme="brutalist-light"], [data-theme="minimalist-light"]), [data-theme="minimalist-light"], [data-theme="minimalist-warm"])) #persistentMiniPlayer {
    background: rgba(18, 18, 23, 0.98) !important;
}

html.is-firefox .visualizerDock {
    background: transparent !important;
}

@supports (-moz-appearance: none) {
    *,
    *::before,
    *::after {
        backdrop-filter: none !important;
        -webkit-backdrop-filter: none !important;
    }
    .ambientAuraGlow {
        filter: none !important;
        animation: none !important;
    }
    .deckArtworkAmbient {
        filter: blur(8px) !important;
    }
    :root:not(:is(:is([data-theme="brutalist-light"], [data-theme="minimalist-light"]), [data-theme="minimalist-light"], [data-theme="minimalist-warm"])) .topBar {
        background: rgba(14, 14, 18, 0.96) !important;
    }
    :root:not(:is(:is([data-theme="brutalist-light"], [data-theme="minimalist-light"]), [data-theme="minimalist-light"], [data-theme="minimalist-warm"])) #mobileTabBar {
        background: rgba(14, 14, 18, 0.97) !important;
    }
    :root:not(:is(:is([data-theme="brutalist-light"], [data-theme="minimalist-light"]), [data-theme="minimalist-light"], [data-theme="minimalist-warm"])) #persistentMiniPlayer {
        background: rgba(18, 18, 23, 0.98) !important;
    }
    .visualizerDock {
        background: transparent !important;
    }
}

/* =========================================================================
   ACCESSIBILITY: PREFERS-REDUCED-MOTION
   Ensures users with vestibular motion sensitivities have instantaneous transitions
   ========================================================================= */
@media (prefers-reduced-motion: reduce) {
    *,
    *::before,
    *::after {
        animation-duration: 0.001ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.001ms !important;
    }
}

