    text-align: center !important;
    margin: auto !important;
    width: 100% !important;
    max-width: 32rem !important;
    box-sizing: border-box !important;
}

.slskRadarGraphic.activeRadar {
    position: relative !important;
    width: 6.5rem !important;
    height: 6.5rem !important;
    border-radius: 50% !important;
    background: radial-gradient(circle, rgba(0, 229, 255, 0.12) 0%, rgba(0, 229, 255, 0.02) 65%, transparent 70%) !important;
    border: none !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    overflow: hidden !important;
    box-shadow: 0 0 25px rgba(0, 229, 255, 0.15) !important;
}

.radarRing {
    position: absolute !important;
    border-radius: 50% !important;
    border: 1px solid rgba(0, 229, 255, 0.35) !important;
    animation: slskRadarPulseWave 2.8s cubic-bezier(0.2, 0.8, 0.2, 1) infinite !important;
}

.radarRing.r1 {
    width: 30% !important;
    height: 30% !important;
    animation-delay: 0s !important;
}

.radarRing.r2 {
    width: 60% !important;
    height: 60% !important;
    animation-delay: 0.9s !important;
}

.radarRing.r3 {
    width: 90% !important;
    height: 90% !important;
    animation-delay: 1.8s !important;
}

@keyframes slskRadarPulseWave {
    0% {
        transform: scale(0.3);
        opacity: 0.9;
    }
    100% {
        transform: scale(1.4);
        opacity: 0;
    }
}

.radarSweep {
    position: absolute !important;
    top: 0 !important;
    left: 0 !important;
    width: 100% !important;
    height: 100% !important;
    border-radius: 50% !important;
    background: conic-gradient(from 0deg, rgba(0, 229, 255, 0.5) 0deg, rgba(0, 229, 255, 0.15) 35deg, transparent 70deg) !important;
    animation: slskRadarSweep 1.8s linear infinite !important;
    pointer-events: none !important;
}

@keyframes slskRadarSweep {
    0% {
        transform: rotate(0deg);
    }
    100% {
        transform: rotate(360deg);
    }
}

.radarCenterPulse {
    position: relative !important;
    width: 0.75rem !important;
    height: 0.75rem !important;
    border-radius: 50% !important;
    background: #00e5ff !important;
    box-shadow: 0 0 12px #00e5ff, 0 0 20px #00e5ff !important;
    z-index: 2 !important;
    animation: slskCorePulse 1.2s ease-in-out infinite alternate !important;
}

@keyframes slskCorePulse {
    0% {
        transform: scale(0.85);
        opacity: 0.75;
    }
    100% {
        transform: scale(1.2);
        opacity: 1;
    }
}

