@media (max-width: 768px) {
    /* Instant Workspace Opacity on Mobile (Zero Mid-Fade Dimming) */
    body.view-settings .settingsWorkspace,
    body.view-soulseek .soulseekWorkspace,
    body.view-download .downloadWorkspace,
    body.view-player .gridContainer {
        animation: none !important;
