/* =============================================================================
   STUDIO PARAMETRIC EQUALIZER (PEQ) WORKSTATION & NEUTRON ENGINE OVERHAUL
   ============================================================================= */

/* PEQ Workstation Modal Card */
.peqModalCard {
    max-width: 960px !important;
    width: 95vw !important;
    background: var(--bg-surface-1, #121217) !important;
    border: 1px solid var(--border-medium, rgba(255, 255, 255, 0.15)) !important;
    box-shadow: 0 20px 50px rgba(0, 0, 0, 0.75), 0 0 25px var(--accent-glow, rgba(0, 229, 255, 0.15)) !important;
    border-radius: 0.75rem !important;
    padding: 1.5rem !important;
    display: flex !important;
    flex-direction: column !important;
    gap: 1.25rem !important;
    max-height: 90vh !important;
    overflow-y: auto !important;
}

.peqHeaderTitle {
    display: flex;
    align-items: center;
    gap: 0.85rem;
}

.peqIcon {
    font-size: 1.6rem;
    line-height: 1;
}

.peqHeaderTitle h3 {
    margin: 0;
    font-size: 1.15rem;
    font-weight: 800;
    letter-spacing: 0.05em;
    color: var(--text-primary, #ffffff);
}

.peqHeaderSub {
    font-size: 0.72rem;
    font-weight: 600;
    letter-spacing: 0.08em;
    color: var(--text-muted, #8e8e93);
    text-transform: uppercase;
}

.peqHeaderActions {
    display: flex;
    align-items: center;
    gap: 0.6rem;
}

.peqBypassBtn {
    display: inline-flex !important;
    align-items: center !important;
    gap: 0.45rem !important;
    height: 2.1rem !important;
    padding: 0 0.85rem !important;
    font-size: 0.75rem !important;
    font-weight: 700 !important;
    border-radius: 0.4rem !important;
    background: rgba(16, 185, 129, 0.15) !important;
    border: 1px solid #10b981 !important;
    color: #10b981 !important;
    cursor: pointer !important;
    transition: all 0.2s ease !important;
}

.peqBypassBtn.bypassed {
    background: rgba(239, 68, 68, 0.15) !important;
    border-color: #ef4444 !important;
    color: #ef4444 !important;
}

.peqBypassDot {
    font-size: 0.75rem;
    line-height: 1;
}

.peqResetBtn {
    height: 2.1rem !important;
    padding: 0 0.85rem !important;
    font-size: 0.75rem !important;
    font-weight: 700 !important;
    border-radius: 0.4rem !important;
    background: var(--bg-surface-2, rgba(255, 255, 255, 0.08)) !important;
    border: 1px solid var(--border-subtle, rgba(255, 255, 255, 0.12)) !important;
    color: var(--text-secondary, #d4d4d8) !important;
    cursor: pointer !important;
}

.peqResetBtn:hover {
    background: var(--bg-surface-3, rgba(255, 255, 255, 0.15)) !important;
    color: var(--text-primary, #ffffff) !important;
}

/* Response Curve Canvas */
.peqCanvasContainer {
    position: relative;
    width: 100%;
    height: 190px;
    background: #09090c;
    border: 1px solid var(--border-medium, rgba(255, 255, 255, 0.15));
    border-radius: 0.5rem;
    overflow: hidden;
}

.peqCurveCanvas {
    width: 100%;
    height: 100%;
    display: block;
}

.peqCanvasOverlay {
    position: absolute;
    top: 0;
    left: 0.6rem;
    bottom: 0;
    pointer-events: none;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    padding: 0.4rem 0;
}

.peqDbLabel {
    font-family: var(--font-mono, monospace);
    font-size: 0.65rem;
    font-weight: 700;
    color: rgba(255, 255, 255, 0.4);
    text-shadow: 0 1px 2px rgba(0, 0, 0, 0.8);
}

.peqDbLabel.mid {
    color: rgba(255, 255, 255, 0.7);
}

/* Toolbar Row: Presets & AutoEq */
.peqToolbarRow {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
    flex-wrap: wrap;
    background: var(--bg-surface-2, rgba(255, 255, 255, 0.04));
    border: 1px solid var(--border-subtle, rgba(255, 255, 255, 0.08));
    border-radius: 0.5rem;
    padding: 0.65rem 0.9rem;
}

.peqPresetGroup {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    flex: 1;
    min-width: 260px;
}

.peqToolbarLabel {
    font-size: 0.72rem;
    font-weight: 800;
    letter-spacing: 0.06em;
    color: var(--text-muted, #a1a1aa);
    white-space: nowrap;
}

.peqSelect {
    height: 2.1rem;
    background: var(--bg-surface-1, #18181b);
    border: 1px solid var(--border-medium, rgba(255, 255, 255, 0.2));
    border-radius: 0.4rem;
    color: var(--text-primary, #ffffff);
    padding: 0 0.8rem;
    font-size: 0.82rem;
    font-weight: 600;
    cursor: pointer;
    outline: none;
    flex: 1;
}

.peqSelect:focus {
    border-color: var(--border-bold, #00e5ff);
}

.peqAutoEqBtn {
    height: 2.1rem !important;
    padding: 0 0.95rem !important;
    font-size: 0.75rem !important;
    font-weight: 700 !important;
    border-radius: 0.4rem !important;
    background: var(--accent-surface, rgba(0, 229, 255, 0.12)) !important;
    border: 1px solid var(--border-bold, #00e5ff) !important;
    color: var(--text-accent, #00e5ff) !important;
    cursor: pointer !important;
    transition: all 0.2s ease !important;
}

.peqAutoEqBtn:hover {
    background: var(--accent-color, #00e5ff) !important;
    color: var(--text-on-accent, #000000) !important;
}

/* AutoEq Drawer */
.peqAutoEqDrawer {
    background: var(--bg-surface-2, rgba(255, 255, 255, 0.05));
    border: 1px solid var(--border-medium, rgba(255, 255, 255, 0.15));
    border-radius: 0.5rem;
    padding: 0.9rem;
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
}

.peqAutoEqTextarea {
    width: 100%;
    height: 80px;
    background: var(--bg-surface-1, #0f0f13);
    border: 1px solid var(--border-subtle, rgba(255, 255, 255, 0.15));
    border-radius: 0.4rem;
    color: var(--text-primary, #ffffff);
    font-family: var(--font-mono, monospace);
    font-size: 0.78rem;
    padding: 0.6rem;
    resize: vertical;
    outline: none;
    box-sizing: border-box;
}

.peqAutoEqTextarea:focus {
    border-color: var(--border-bold, #00e5ff);
}

.peqAutoEqDrawerActions {
    display: flex;
    align-items: center;
    gap: 0.6rem;
    flex-wrap: wrap;
}

.peqAutoEqHint {
    font-size: 0.7rem;
    color: var(--text-muted, #71717a);
    margin-left: auto;
}

/* 10-Band Faders Strip */
.peqFadersGrid {
    display: grid;
    grid-template-columns: repeat(10, 1fr);
    gap: 0.5rem;
    background: var(--bg-surface-2, rgba(255, 255, 255, 0.03));
    border: 1px solid var(--border-subtle, rgba(255, 255, 255, 0.08));
    border-radius: 0.5rem;
    padding: 1rem 0.5rem 0.75rem 0.5rem;
    min-height: 230px;
}

.peqFaderCol {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.45rem;
    position: relative;
}

.peqFaderDb {
    font-family: var(--font-mono, monospace);
    font-size: 0.72rem;
    font-weight: 700;
    color: var(--text-primary, #ffffff);
    min-height: 1.1rem;
    transition: color 0.15s ease;
}

.peqFaderDb.boost {
    color: #10b981;
}

.peqFaderDb.cut {
    color: #ef4444;
}

.peqFaderTrackCon {
    height: 140px;
    display: flex;
    align-items: center;
    justify-content: center;
    position: relative;
    width: 28px;
}

.peqFaderTrackZero {
    position: absolute;
    top: 50%;
    left: 4px;
    right: 4px;
    height: 1px;
    background: var(--border-medium, rgba(255, 255, 255, 0.25));
    pointer-events: none;
}

.peqSlider {
    writing-mode: vertical-lr;
    direction: rtl;
    width: 24px;
    height: 130px;
    background: transparent;
    cursor: pointer;
    outline: none;
}

.peqFaderHz {
    font-family: var(--font-mono, monospace);
    font-size: 0.72rem;
    font-weight: 700;
    color: var(--text-muted, #a1a1aa);
    letter-spacing: 0.02em;
}

