/* STUDIO DSP & EQUALIZER DECK SEPARATION MODULE ARCHITECTURE                */
/* ========================================================================= */

.audioProcessingBar {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 100%;
    max-width: 34rem;
    margin: 0.25rem auto 0.12rem auto;
    flex-shrink: 0;
}

.eqDeckModule {
    width: 100%;
    display: flex;
    justify-content: center;
}

.eqDeckBtn {
    display: flex;
    align-items: center;
    justify-content: space-between;
    width: 100%;
    padding: 0.52rem 1.05rem;
    background: var(--card-bg, #1e293b);
    border: 1.5px solid var(--border-color, rgba(255, 255, 255, 0.16));
    border-radius: 10px;
    color: var(--text-primary, #ffffff);
    cursor: pointer;
    transition: all 0.22s cubic-bezier(0.16, 1, 0.3, 1), transform 0.12s ease;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.2);
    text-decoration: none;
    box-sizing: border-box;
}

.eqDeckBtn:hover {
    border-color: var(--accent-color, #00e5ff);
    background: rgba(255, 255, 255, 0.08);
    transform: translateY(-1px);
    box-shadow: 0 4px 14px rgba(0, 0, 0, 0.35);
}

.eqDeckBtn.active {
    border-color: var(--accent-color, #00e5ff);
    box-shadow: 0 0 14px var(--accent-glow, rgba(0, 229, 255, 0.25));
}

.eqDeckInfo {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: 0.15rem;
    text-align: left;
}

.eqDeckTitle {
    font-size: 0.76rem;
    font-weight: 800;
    letter-spacing: 0.06em;
    color: var(--text-primary, #ffffff);
    line-height: 1.15;
}

.eqDeckSub {
    font-size: 0.6rem;
    font-weight: 600;
    letter-spacing: 0.04em;
    color: var(--text-secondary, #94a3b8);
    line-height: 1.2;
}

.eqDeckBadges {
    display: flex;
    align-items: center;
    gap: 0.4rem;
}

.eqDeckBadge {
    display: inline-flex;
    align-items: center;
    padding: 0.18rem 0.5rem;
    background: rgba(255, 255, 255, 0.1);
    color: var(--text-secondary, #94a3b8);
    border: 1px solid rgba(255, 255, 255, 0.16);
    border-radius: 4px;
    font-size: 0.62rem;
    font-weight: 800;
    letter-spacing: 0.04em;
    transition: all 0.2s ease;
