/* ========================================================================= */
/* Collapsible / Sliding Metadata Inspector Panel                            */
/* ========================================================================= */
.gridContainer {
    transition: grid-template-columns 0.35s cubic-bezier(0.16, 1, 0.3, 1), gap 0.35s cubic-bezier(0.16, 1, 0.3, 1);
}

.settingsPanel {
    transition: transform 0.35s cubic-bezier(0.16, 1, 0.3, 1),
                opacity 0.28s cubic-bezier(0.16, 1, 0.3, 1),
                max-width 0.35s cubic-bezier(0.16, 1, 0.3, 1),
                min-width 0.35s cubic-bezier(0.16, 1, 0.3, 1),
                width 0.35s cubic-bezier(0.16, 1, 0.3, 1),
                padding 0.35s cubic-bezier(0.16, 1, 0.3, 1),
                margin 0.35s cubic-bezier(0.16, 1, 0.3, 1);
    transform-origin: left center;
    will-change: transform, opacity;
}

@media (min-width: 1025px) {
    body.metadata-collapsed .gridContainer {
        grid-template-columns: 0px 1fr minmax(18rem, 25rem) !important;
        gap: 0 clamp(0.5rem, 1vw, 1.2rem) !important;
    }

    body.metadata-collapsed .turntableStage {
        max-height: 48vh !important;
    }

    body.metadata-collapsed .turntableCon {
        --turntable-size: clamp(14.5rem, min(85cqi, 44dvh), 27rem) !important;
    }

    body.metadata-collapsed .settingsPanel {
        opacity: 0 !important;
        pointer-events: none !important;
        transform: translateX(-45px) scaleX(0.7) !important;
        max-width: 0 !important;
        min-width: 0 !important;
        width: 0 !important;
        padding-left: 0 !important;
        padding-right: 0 !important;
        margin-left: 0 !important;
        margin-right: 0 !important;
        border-width: 0 !important;
        overflow: hidden !important;
        visibility: hidden !important;
    }
}

@media (max-width: 1024px) and (min-width: 769px) {
    body.metadata-collapsed .gridContainer {
        grid-template-columns: 0px 1fr minmax(17rem, 20.5rem) !important;
        gap: 0 0.6rem !important;
    }

    body.metadata-collapsed .settingsPanel {
        opacity: 0 !important;
        pointer-events: none !important;
        max-width: 0 !important;
        min-width: 0 !important;
        width: 0 !important;
        padding: 0 !important;
        margin: 0 !important;
        border-width: 0 !important;
        display: none !important;
    }
}

